-- Phase I: forward-only commerce truth. Phase H remains the product, entitlement, slot and account-binding authority.
alter table public.phase_h_products add column if not exists product_kind text not null default 'ACCESS', add column if not exists metadata_version text not null default 'phase-i/1';
update public.phase_h_products set active=false where code='FOUNDING_PROP_EXECUTION';
insert into public.phase_h_products(code,name,price_cents,currency,billing_interval,checkout_state,capacity,terms_version,features,product_kind,metadata_version) values
 ('FREE_SIGNALS','Free Signals',0,'USD',null,'READY_FOR_CONFIGURATION',null,'2026.09','{"free_telegram":true,"vip":false,"execution":false}','FREE','phase-i/1'),
 ('VIP_SIGNALS','VIP Signals',2900,'USD','month','READY_FOR_CONFIGURATION',null,'2026.09','{"vip_signals":true,"execution":false}','SUBSCRIPTION','phase-i/1'),
 ('FOUNDING_AUTO_EXECUTION','Founding 20 Auto Execution',10000,'USD','month','READY_FOR_CONFIGURATION',20,'2026.09','{"execution_accounts":1,"provider_neutral":true}','SUBSCRIPTION','phase-i/1')
on conflict(code) do update set name=excluded.name,price_cents=excluded.price_cents,currency=excluded.currency,billing_interval=excluded.billing_interval,capacity=excluded.capacity,features=excluded.features,product_kind=excluded.product_kind,metadata_version=excluded.metadata_version;

create table public.commerce_product_prices(
 id uuid primary key default gen_random_uuid(), product_code text not null references public.phase_h_products(code), currency text not null check(currency ~ '^[A-Z]{3}$'), amount_minor bigint not null check(amount_minor>=0), billing_interval text, provider text not null check(provider in('WHOP','MPESA')), version integer not null default 1, active boolean not null default true, configured boolean not null default false, fixed_period_days integer, created_at timestamptz not null default now(), unique(product_code,currency,provider,version)
);
insert into public.commerce_product_prices(product_code,currency,amount_minor,billing_interval,provider,configured,fixed_period_days) values
 ('VIP_SIGNALS','USD',2900,'month','WHOP',false,null),('VIP_SIGNALS','KES',350000,'fixed_period','MPESA',false,30),('FOUNDING_AUTO_EXECUTION','USD',10000,'month','WHOP',false,null) on conflict do nothing;

alter table public.founding_slot_reservations drop constraint if exists founding_slot_reservations_slot_number_check;
alter table public.founding_slot_reservations add constraint founding_slot_reservations_slot_number_check check(slot_number between 1 and 20);
alter table public.founding_slot_reservations add column if not exists checkout_session_id uuid, add column if not exists activated_at timestamptz, add column if not exists released_at timestamptz;

create table public.commerce_checkout_sessions(
 id uuid primary key default gen_random_uuid(), customer_id uuid not null references auth.users(id), product_code text not null references public.phase_h_products(code), provider text not null check(provider in('WHOP','MPESA')), currency text not null, amount_minor bigint not null, price_version integer not null, billing_interval text, execution_account_id uuid references public.connected_execution_accounts(id), additional_account_request_id uuid references public.additional_account_requests(id), founding_reservation_id uuid references public.founding_slot_reservations(id), external_reference text, idempotency_key text not null, status text not null check(status in('CREATED','SLOT_RESERVED','PROVIDER_PENDING','ACTION_REQUIRED','COMPLETED','EXPIRED','CANCELLED','FAILED','REVIEW_REQUIRED')), safe_return_url text not null, campaign text, affiliate text, metadata_version text not null default 'phase-i/1', expires_at timestamptz not null, completed_at timestamptz, created_at timestamptz not null default now(), unique(customer_id,idempotency_key)
);
alter table public.founding_slot_reservations add constraint founding_slot_checkout_fk foreign key(checkout_session_id) references public.commerce_checkout_sessions(id) deferrable initially deferred;
create unique index commerce_one_active_checkout on public.commerce_checkout_sessions(customer_id,product_code,coalesce(execution_account_id,'00000000-0000-0000-0000-000000000000'::uuid)) where status in('CREATED','SLOT_RESERVED','PROVIDER_PENDING','ACTION_REQUIRED');
create table public.commerce_payment_attempts(
 id uuid primary key default gen_random_uuid(), checkout_session_id uuid not null references public.commerce_checkout_sessions(id), customer_id uuid not null references auth.users(id), provider text not null check(provider in('WHOP','MPESA')), external_reference text, amount_minor bigint not null, currency text not null, provider_state text, state text not null check(state in('CREATED','PENDING','AUTHORIZED','SUCCEEDED','FAILED','CANCELLED','EXPIRED','REFUNDED','PARTIALLY_REFUNDED','DISPUTED','CHARGEBACK','REVERSED','REVIEW_REQUIRED')), requested_at timestamptz not null default now(), confirmed_at timestamptz, reason_code text, safe_evidence jsonb not null default '{}', idempotency_key text not null unique, reconciliation_state text not null default 'NOT_REQUIRED'
);
create unique index commerce_provider_payment_ref on public.commerce_payment_attempts(provider,external_reference) where external_reference is not null;
create table public.commerce_payment_events(
 id uuid primary key default gen_random_uuid(), provider text not null check(provider in('WHOP','MPESA')), external_event_id text not null, event_type text not null, received_at timestamptz not null default now(), signature_verified boolean not null, processing_state text not null check(processing_state in('RECEIVED','PROCESSING','PROCESSED','REJECTED','FAILED','DEAD_LETTER')), processing_attempts integer not null default 0, processed_at timestamptz, safe_error text, payload_hash text not null, restricted_payload jsonb, retention_until timestamptz, unique(provider,external_event_id)
);
create table public.commerce_subscriptions(
 id uuid primary key default gen_random_uuid(), customer_id uuid not null references auth.users(id), product_code text not null references public.phase_h_products(code), provider text not null, external_reference text, status text not null check(status in('PENDING','ACTIVE','GRACE','PAST_DUE','CANCEL_AT_PERIOD_END','CANCELLED','EXPIRED','SUSPENDED','REFUNDED','DISPUTED')), current_period_start timestamptz,current_period_end timestamptz,grace_end timestamptz,cancel_at_period_end boolean not null default false,cancelled_at timestamptz,expired_at timestamptz,amount_minor bigint not null,currency text not null,price_version integer not null,renewal_count integer not null default 0,last_verified_payment_id uuid references public.commerce_payment_attempts(id),next_expected_payment timestamptz,entitlement_state text not null default 'PENDING',unique(provider,external_reference)
);
alter table public.phase_h_entitlements add column if not exists source_subscription_id uuid references public.commerce_subscriptions(id), add column if not exists source_payment_id uuid references public.commerce_payment_attempts(id), add column if not exists execution_account_id uuid references public.connected_execution_accounts(id), add column if not exists founding_reservation_id uuid references public.founding_slot_reservations(id), add column if not exists granted_at timestamptz, add column if not exists revoked_at timestamptz, add column if not exists grant_reason text, add column if not exists revoke_reason text, add column if not exists commercial_version text not null default 'phase-i/1';
create unique index phase_i_one_entitlement_per_account on public.phase_h_entitlements(execution_account_id) where execution_account_id is not null and state in('ACTIVE','TRIAL','GRACE');
create table public.commerce_refund_disputes(id uuid primary key default gen_random_uuid(),payment_id uuid not null references public.commerce_payment_attempts(id),provider text not null,provider_reference text not null,amount_minor bigint not null,currency text not null,case_type text not null check(case_type in('REFUND','PARTIAL_REFUND','CHARGEBACK','DISPUTE','REVERSAL')),state text not null,evidence_at timestamptz not null,entitlement_action text not null,admin_review_required boolean not null default false,created_at timestamptz not null default now(),unique(provider,provider_reference));
create table public.telegram_fulfillment_requests(id uuid primary key default gen_random_uuid(),customer_id uuid not null references auth.users(id),entitlement_id uuid not null references public.phase_h_entitlements(id),access_type text not null,audience text not null,action text not null check(action in('ADD','RESTORE','REMOVE','SUSPEND')),status text not null default 'PENDING' check(status in('PENDING','CLAIMED','COMPLETED','FAILED','DEAD_LETTER')),idempotency_key text not null unique,attempt_count integer not null default 0,safe_error text,created_at timestamptz not null default now(),processed_at timestamptz);
create table public.commerce_manual_reviews(id uuid primary key default gen_random_uuid(),customer_id uuid references auth.users(id),checkout_session_id uuid references public.commerce_checkout_sessions(id),payment_id uuid references public.commerce_payment_attempts(id),reason_code text not null,status text not null default 'OPEN',resolution text,resolved_by uuid,resolved_at timestamptz,created_at timestamptz not null default now());
create table public.commerce_audit_events(id uuid primary key default gen_random_uuid(),customer_id uuid,actor_id uuid,event_type text not null,checkout_session_id uuid,payment_id uuid,safe_metadata jsonb not null default '{}',created_at timestamptz not null default now());

-- Customer visibility is owner-only; all mutation is service-role RPC/Edge authority only.
alter table public.commerce_product_prices enable row level security; alter table public.commerce_checkout_sessions enable row level security; alter table public.commerce_payment_attempts enable row level security; alter table public.commerce_payment_events enable row level security; alter table public.commerce_subscriptions enable row level security; alter table public.commerce_refund_disputes enable row level security; alter table public.telegram_fulfillment_requests enable row level security; alter table public.commerce_manual_reviews enable row level security; alter table public.commerce_audit_events enable row level security;
create policy commerce_prices_read on public.commerce_product_prices for select using(active);
create policy checkout_owner_read on public.commerce_checkout_sessions for select to authenticated using(customer_id=auth.uid() or public.is_admin());
create policy payment_owner_read on public.commerce_payment_attempts for select to authenticated using(customer_id=auth.uid() or public.is_admin());
create policy subscription_owner_read on public.commerce_subscriptions for select to authenticated using(customer_id=auth.uid() or public.is_admin());
create policy telegram_request_owner_read on public.telegram_fulfillment_requests for select to authenticated using(customer_id=auth.uid() or public.is_admin());
create policy audit_owner_read on public.commerce_audit_events for select to authenticated using(customer_id=auth.uid() or public.is_admin());
revoke all on public.commerce_checkout_sessions,public.commerce_payment_attempts,public.commerce_payment_events,public.commerce_subscriptions,public.commerce_refund_disputes,public.telegram_fulfillment_requests,public.commerce_manual_reviews,public.commerce_audit_events from anon,authenticated;
grant select on public.commerce_product_prices to anon,authenticated; grant select on public.commerce_checkout_sessions,public.commerce_payment_attempts,public.commerce_subscriptions,public.telegram_fulfillment_requests,public.commerce_audit_events to authenticated;

create or replace function public.reserve_founding_slot(p_customer uuid,p_checkout uuid,p_expires timestamptz) returns public.founding_slot_reservations language plpgsql security definer set search_path=public as $$
declare n integer; r public.founding_slot_reservations; begin
 perform pg_advisory_xact_lock(hashtext('FOUNDING_AUTO_EXECUTION'));
 update founding_slot_reservations set state='EXPIRED',released_at=now() where state='RESERVED' and expires_at<=now();
 select s into n from generate_series(1,20) s where not exists(select 1 from founding_slot_reservations f where f.slot_number=s and f.state in('RESERVED','ACTIVE')) order by s limit 1;
 if n is null then raise exception 'FOUNDING_CAPACITY_EXHAUSTED'; end if;
 insert into founding_slot_reservations(customer_id,slot_number,state,expires_at,terms_version,checkout_session_id) values(p_customer,n,'RESERVED',p_expires,'2026.09',p_checkout) returning * into r; return r; end $$;
revoke all on function public.reserve_founding_slot(uuid,uuid,timestamptz) from public; grant execute on function public.reserve_founding_slot(uuid,uuid,timestamptz) to service_role;

create or replace view public.commerce_receipts_safe with(security_invoker=true) as select p.id,p.customer_id,p.confirmed_at,p.amount_minor,p.currency,p.provider,case when length(p.external_reference)>6 then left(p.external_reference,3)||'••••'||right(p.external_reference,3) else '••••' end safe_reference,c.product_code from commerce_payment_attempts p join commerce_checkout_sessions c on c.id=p.checkout_session_id where p.state in('SUCCEEDED','REFUNDED','PARTIALLY_REFUNDED','DISPUTED','CHARGEBACK','REVERSED');
grant select on public.commerce_receipts_safe to authenticated;
